                    (27, "body", "cabu[n]t. Si in: 10: die arge[n]tu[m] me[n]liu[m?] fiet in t[er]ra. Si in: 11: die mortalitate[m] hominu[m] significat. Si in: 12: die soll", "multiply. If on the 10th day, silver [and honey?] shall be on the earth. If on the 11th day, it signifies mortality of men. If on the 12th day, [if] the sun", ""),
                    (28, "body", "luce[m] videat[ur] in illo ano multe infirmitates er[u]nt int[er] gentes. :- :- :- :- :-", "is seen to shine, in that year there shall be many infirmities among nations.", "Followed by decorative line-filler dashes."),
                    (29, "body", "§ Anno D[omi]nj 1592 Died all the Baye trees in Englande aboue ground but reuiued", "In the year of the Lord 1592, all the bay trees in England died above ground, but revived", "Written by Henry Dingley."),
                    (30, "body", "at the Rootes for the most parte wherof I had twooe in my Gardeyn: /", "at the roots for the most part, whereof I had two in my garden.", ""),
                    (31, "signature", "henry Dingley", "Henry Dingley", "Signature of Henry Dingley."),
                    (32, "body", "§ Anno D[omi]nj 1598 no frute Apples nor peares [cancelled]", "In the year of the Lord 1598, no fruit, apples nor pears [...]", "Followed by heavy ink cancellation."),
                    (33, "marginalia", "1624", "1624", "Date jotted below '1598'."),
